"""Finite analyst MIDI Tools documentary successor. No application/source execution."""
from pathlib import Path
from copy import deepcopy
import json,sys
P=Path(__file__).resolve().parent;ROOT=P.parents[3];A=P.parent/'midi-tools-source-audit'
def load(p):return json.loads(p.read_text())
def dump(v):return json.dumps(v,indent=2,ensure_ascii=False)+'\n'
def rows(t):return {c[0]:c for l in t.splitlines() if l.startswith('| REQ-MIDI-EDIT-') for c in [[s.strip() for s in l.strip('|').split('|')]]}
def build():
 plan=load(P/'tools-increment-r4.json');audit=load(A/'audit.json');old=load(P/'acceptance-cases-r3.json');cat=deepcopy(old);cat['format_revision']=4
 cat['provenance']='R4 preserves all72 R3 records verbatim and appends21 bounded Tools control/action proposals; legacy expected/comparator are documentary, never target measurements.'
 cat['actual_result_status']=dict(role='Explicit current status of all93 records, not historical measurement: legacy fields remain documentary proposals; first72 records preserved verbatim.',actual_expected=None,actual_comparison=None,target_grade='U',executed=False)
 guard=dict(independently_owned_admitted_editable_target=True,transformer_nonempty_input=True,generator_initial_empty_allowed=True,actual_nonempty_output_before_generator_bounds_capacity_origin_absence=True,productive_matched_operation_before_negative=True,separate_exact_original_reset=True,hardware_required_for_editor_data=False,failed_prerequisite_stays_U=True)
 common='Use separate disposable independently valid owned MIDI targets, explicit actual tool/tab/focus/selection/loop/grid/scale/Auto Apply state, accepted controls and exact original resets. A transformer needs nonempty input; a generator may start empty but needs actual NONEMPTY generated output before bounds/capacity/origin/absence. A flag alone is insufficient. Productive matched effects precede negative/no-effect/disabled/zero comparisons; failed prerequisites stay U. Pure editor-data actions need no hardware/audio; any audible observation separately needs eligible active nonzero expression/route/depth and nonmuted productive output. '
 for i,g in enumerate(plan['groups']):
  ap=audit['proposals'][i];assert ap['id']==g['group']
  refs=[dict(catalog=str((A/'audit.json').relative_to(ROOT)),json_pointer='/blocks/'+str(int(b[-3:])-1),block=b) for b in ap['source_blocks']]
  c=dict(id=f'MED-{73+i:03}',requirement=g['requirement'],kind=ap['title'],setup_action=common+g['action'],expected=None,comparator=None,documentary_expected=g['documentary_expected'],documentary_comparator=g['documentary_comparator'],source_claim=' '.join(audit['blocks'][int(b[-3:])-1]['text'] for b in ap['source_blocks']),documented_domain_grade=g['grade'],target_12_4_3_grade='U',evidence='Retained current Version12 MIDI Tools; exact 12.4.3 applicability U',execution='not-run',actual_expected=None,actual_comparison=None,source_contexts=refs,adoption_group=g['group'],fixture='fixtures-r4.json#MIDI-TOOLS-OWNED-R4',positive_guard=deepcopy(guard))
  if i in [7,8]:c['related_current_owner_contexts']=[dict(catalog='analysis/ableton-live-12.4.3/full-spec-v1/mpe-tuning-grooves/mpe-cases-r3.json',json_pointer=f'/{n}',role='Generic MPE lane/mode or folded-note gesture only; not tool-display equivalence or C3 closure') for n in [29,30,41]]
  if i==3:c['related_audit_contexts']=[dict(catalog=str((A/'audit.json').relative_to(ROOT)),json_pointer=f'/external_contexts/{n}',role='Only quoted selected Max/Browser roles; no generic-owner closure') for n in range(4,22)]
  cat['cases'].append(c)
 oldspec=(P/'spec-before-r4.md').read_text();spec=oldspec.replace('revision: 3\n','revision: 4\n',1);before=rows(oldspec);after={k:list(v) for k,v in before.items()}
 for g in plan['groups']:after[g['requirement']][3]+=' '+g['clause_append']
 for k in before:
  if before[k]!=after[k]:spec=spec.replace('| '+' | '.join(before[k])+' |','| '+' | '.join(after[k])+' |')
 spec=spec.replace('## R3 bounded gesture and case increment','## Historical R3 bounded gesture and case increment')
 start=spec.index('## Acceptance cases\n');end=spec.index('## Interval acceptance contexts and Q053',start)
 spec=spec[:start]+"""## Acceptance cases

[Current R4 cases](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/acceptance-cases-r4.json)
contain93records:77D12 documentary proposals and16U cases. All72R3 records
remain verbatim, including twelve gesture histories and the seventeen old tool
actions. MED073–093 add bounded Tools controls/gestures. Three new named-control
documentary comparisons are nonnull and eighteen are null; all new legacy
expected/comparator pairs are null. All actual outcomes remain null/U/unexecuted.

Existing finite FitScale, Stretch/Humanize, Span and Seed documentary examples
remain exact old records; no numeric law is newly adopted here. MED020 performs
foreground Velocity and MED072 adds Chance. MED086 supplies the productive
nonzero Strum history absent from historical zero-only MED036. Generator bounds/
capacity/origin/absence probes require actual NONEMPTY output, not Density flags;
empty initial generator targets remain allowed. C1/C2/C3 and implicit-loop/input
context remain unknown. No fixture or original tool action is supplied or run.

"""+spec[end:]
 spec=spec.replace('[Packet manifest]', '[Original R1 packet manifest]').replace('pins payload hashes; its final spec/research hashes freeze this review snapshot.','pins original R1 payload hashes and its historical spec/research snapshot; current R4 routes are above.')
 spec=spec.replace('## Interval acceptance contexts and Q053','## Historical R2 Interval acceptance contexts and Q053')
 spec=spec.replace('All17tool rows/actions exact; current owner review pending as of author freeze. |','All17tool rows/actions exact; current owner review pending as of author freeze. |\n| 4 | 2026-10-19 | Same43IDs;21bounded common/tool control refinements and93cases;72old records exact plus21Tools proposals. All actual outcomesU/unexecuted; review pending as of author freeze. |',1)
 spec+='''\n## R4 bounded MIDI Tools control and action increment\n\nThe [complete retained Tools audit](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-tools-source-audit/README.md)\nand its [independent partial review](../../analysis/ableton-live-12.4.3/full-spec-v1/reviews/midi-tools-source-audit-review.json)\nsupport bounded additions to existing023–043;001–022 remain exact current R3.\nThe [current93-case catalog](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/acceptance-cases-r4.json)\nretains all72old records, including twelve gesture cases, and adds MED073–093.\nThere are77D12 documentary proposals and16U; all actual outcomes are null/U/unexecuted.\nOnly three new named-control documentary comparisons are nonnull; the other18\nnew documentary comparisons, and all21 new legacy expected/comparator pairs,\nare null. Historical numeric documentary examples stay historical and unchanged.\n\nEach of21audit groups contributes a limited control/entry/action subset, not\nfull algorithm or lifecycle closure. Independent admitted controls, exact resets\nand genuinely productive matched effects are mandatory before negatives.\nGenerators may start empty; actual NONEMPTY output precedes range/capacity/origin/\nabsence checks, not a nonzero Density flag. MED086 adds nonzero Strum before\nreset to zero; old MED036 remains the historical zero-only trial. Editor data\nneeds no hardware/audio. Max bundled Standard/Suite selection is separate from\nSuite or Standard plus Max for Live add-on editing/building/third-party context.\nTool display gestures do not duplicate generic MPE lane editing or settle C3.\n\nC1/C2/C3, MTA-Q04 implicit-loop/input context, selection precedence, built-in editability,\nQ052/Q053 and source-silent malformed/cancel/save/undo/transport/teardown/rate\noutcomes remain open. Random reapplication need not differ. No new waveform,\ncurve, arithmetic, RNG, protocol, file, timeline-insertion or timing law is adopted.\n[Exact delta](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/delta-r4.json),\n[guards](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/fixtures-r4.json)\nand [historical consumers](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/consumer-impact-r4.json)\npreserve old files and as-of providers without automatic historical replay.\n**AS-OF AUTHOR FREEZE:** R4 independent owner review pending; the [spec index](index.md)\nowns current disposition. No full family or exact-build completion is claimed.\n'''
 research=(P/'research-before-r4.md').read_text().replace('revision: 3\n','revision: 4\n',1).replace('## R3 bounded editor gesture adoption','## Historical R3 bounded editor gesture adoption').replace('## R2 Interval case increment','## Historical R2 Interval case increment').replace('[manifest]','[original R1 manifest]').replace('pins all packet payloads and the authored spec/research review snapshot.','pins its original R1 payloads and historical spec/research snapshot. The current R4 catalog and checks are routed below.')
 research+='''\n## R4 bounded Tools adoption\n\nThe now [independently reviewed Tools audit](../../analysis/ableton-live-12.4.3/full-spec-v1/reviews/midi-tools-source-audit-review.json)\nassessed all146retained blocks/302manual judgments/21proposals and30selected\nexternal contexts. Images/pixels and17link destinations were not inspected.\nThat audit used immutable R2; R4 starts from current R3, preserves all43IDs and\n72cases, including root's six refined gesture rows and twelve gesture cases.\nRows023–043 append bounded control/entry roles; no new normative ID is added.\nThe [current catalog](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/acceptance-cases-r4.json)\nis93cases:77D12/16U, all actual null/U/not-run. New MED073–093 add21compound\nreset proposals; only three named categorical documentary comparators are nonnull.\nAll new numerical, expression, file, signal, RNG and timing documentary comparators\nare null. Legacy expected/comparator values remain documentary proposals only.\n\nAll21groups are adopted only in the bounded subsets recorded by the\n[increment](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/tools-increment-r4.json).\nGenerator targets may initially be empty; actual NONEMPTY output, not Density,\nprecedes bounds/capacity/origin/absence. Productive nonzero Strum now precedes\nzero reset in MED086; the old zero-only MED036 is unchanged. Current MPE3 mode/\nlane/folded-note gestures are selected context, not Glissando tool-display\nequivalence. Bundled Standard/Suite availability is separate from editing/building/\nthird-party Max prerequisites. No default or hidden build capability is inferred.\n\nSource Version12, unspecified publication revision, capture date2026-10-19\nand unknown exact UTC do not prove12.4.3. C1/C2/C3, loop/selection priority,\nMTA-Q04 implicit-loop/input context, built-in editability, Q052/Q053 and source-silent failure/cancel/undo/\npersistence/transport/teardown/rate remain U. Random output need not differ;\nChop pattern replacement supplies no timeline-insertion law. No full tool-family\ncompletion or new numeric/DSP/curve/RNG/codec/protocol law follows.\n\nAll38prior files remain exact in place, with exact before-canonical snapshots.\nThe [consumer inventory](../../analysis/ableton-live-12.4.3/full-spec-v1/midi-editing/consumer-impact-r4.json)\nretains four qualified old-hash occurrences in one review, as-of only. No old\nconsumer/checker is modified/replayed and no adapter or mutable external gate\nis added. Current own immutable pins, delta, guards and independent review govern.\n**AS-OF AUTHOR FREEZE:** R4 independent review pending; [spec index](../specs/index.md)\nowns current disposition. No original/vendor/native/UI/audio/MIDI/hardware/network/\ninstall/candidate operation or source recapture ran.\n'''
 delta=dict(requirements=43,unchanged_gesture_rows=list(before)[:22],changed_fields=[dict(id=k,column=i,before=before[k][i],after=after[k][i]) for k in before for i in range(5) if before[k][i]!=after[k][i]],old_cases_exact=72,new_case_ids=[c['id'] for c in cat['cases'][72:]],cases=93,documentary_D12=77,documentary_U=16,new_named_documentary_comparators=3,new_null_documentary_comparators=18,all_actual_null=True,executed=0,complete_topics=0,partial_adopted_groups=[g['group'] for g in plan['groups']],unresolved=plan['no_resolution'])
 fixture=dict(id='MIDI-TOOLS-OWNED-R4',guard=guard,common=common,unresolved=plan['no_resolution'],unknown_lifecycle=['malformed','cancel','undo-granularity','persistence','transport','source-loss','rate','teardown'],actual_expected=None,actual_comparison=None,target='U',execution='not-run')
 return {'acceptance-cases-r4.json':dump(cat),'delta-r4.json':dump(delta),'fixtures-r4.json':dump(fixture),'spec-r4.md':spec,'research-r4.md':research}
def main():
 assert sys.dont_write_bytecode and sys.argv[1:] in [['--write'],['--check']]
 if sys.argv[1:] == ['--write']:
  assert not (P/'manifest-author-r4.json').exists(),'sealed: refuse overwrite'
  out=build()
  for n,t in out.items():assert not (P/n).exists(),'refuse existing successor output: '+n
  for n,t in out.items():(P/n).write_text(t)
  (ROOT/'wiki/specs/midi-editing-tools.md').write_text(out['spec-r4.md']);(ROOT/'wiki/research/midi-editing-tools.md').write_text(out['research-r4.md'])
 else:
  for n,t in build().items():assert (P/n).read_text()==t,n
  assert (ROOT/'wiki/specs/midi-editing-tools.md').read_bytes()==(P/'spec-r4.md').read_bytes()
  assert (ROOT/'wiki/research/midi-editing-tools.md').read_bytes()==(P/'research-r4.md').read_bytes()
  print('deterministic R4 --check pass; no writes')
if __name__=='__main__':main()
